parameters.jsCode:
const e = $input.first().json;
const exec = e.execution || {};
const err = exec.error || e.error || {};
const wf = e.workflow || {};
const get = (v, fb) => (v === undefined || v === null || v === '' ? fb : v);
const esc = s => String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
return [{ json: {
    workflow_name: esc(get(wf.name, '?')),
    workflow_id: get(wf.id, '?'),
    execution_id: get(exec.id, '?'),
    node_name: esc(get(err.node && err.node.name, get(exec.lastNodeExecuted, '?'))),
    error_message: esc(String(get(err.message, 'unknown')).slice(0, 500)),
    platform: get(e.platform, 'unknown'),
    content_id: get(e.content_id, 'unknown'),
    timestamp: new Date().toISOString()
}}];

